import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

// Calculator-specific copy. Amount examples are checked against the current engine; policy scope is stated separately.
export const auSgPayrollTaxFollowups: Partial<Record<SupportedLocale, LocaleFollowup>> = {
  ko: {
    "australia-gross-net-salary-calculator": { description: "호주 거주자의 2026–27 연봉을 기준으로 누진 소득세와 단순 2% Medicare levy를 차감해 세후 추정액을 보여줍니다. 저소득 감면·면제, Medicare levy surcharge, 공제 및 비거주자 규칙은 판정하지 않습니다.", howTo: "연간 또는 월간 급여를 선택하고 세전 금액을 입력하세요. 월 급여는 12개월로 환산되며, 결과의 세금·보험료 항목을 따로 확인하세요.", formula: "연소득 = 입력 급여 × (월 입력이면 12). 소득세는 2026–27 거주자 누진 구간별 과세액의 합이며, Medicare levy는 엔진에서 연소득의 2%로 계산합니다. 세후 연소득 = 연소득 − 소득세 − levy.", exampleNote: "연 AUD 80,000을 넣으면 소득세 AUD 14,520, 단순 levy AUD 1,600, 세후 연액 AUD 63,880, 월 환산 AUD 5,323.33입니다. 개인별 감면과 공제 전의 엔진 결과입니다.", faq: { question: "실제 급여명세서의 실수령액과 왜 다를 수 있나요?", answer: "세금 감면·공제, 비거주자 여부, 학자금 대출 상환, 고용주 원천징수와 개인 사정이 반영되지 않은 추정이기 때문입니다." } },
    "singapore-gross-net-salary-calculator": { description: "싱가포르 거주자 누진소득세와 연령별 직원 CPF를 이용한 급여 추정입니다. 비거주자 세율, 세금 감면, 추가 임금, 초기 영주권자 단계 요율은 계산하지 않습니다.", howTo: "CPF 계산 기준을 맞추려면 급여 주기를 월간으로 선택하고 월 세전 급여와 나이를 입력하세요. 이 계산기는 고용주 CPF를 직원 실수령액에서 빼지 않습니다.", formula: "월 급여 입력은 연액으로 ×12 환산해 거주자 누진세를 계산합니다. 직원 CPF는 min(입력 월급, SGD 8,000) × 연령별 직원 요율 ×12로 연간화하고, 이를 세전 연봉과 세금에서 차감합니다.", exampleNote: "월 SGD 6,000, 나이 35세이면 연소득 SGD 72,000, 추정 소득세 SGD 2,790, 직원 CPF 연 SGD 14,400, 세후 연 SGD 54,810(월 SGD 4,567.50)입니다. 고용주 부담분은 별도입니다.", faq: { question: "연간 급여로 입력해도 CPF가 정확한가요?", answer: "CPF는 월별 임금과 한도에 따라 계산됩니다. 월간 모드를 사용하세요. 연간 모드의 CPF 결과는 월별 기여 산식을 그대로 적용하지 않으므로 공식 산정액으로 사용하지 마세요." } },
    "singapore-income-tax-calculator": { description: "입력한 싱가포르 거주자 연간 과세소득에 2024 YA 이후의 누진 세율표를 적용해 소득세와 평균세율을 추정합니다. 비거주자 세율, 개인 공제·감면과 환급은 포함하지 않습니다.", howTo: "공제 반영 후의 과세소득에 가까운 연간 금액을 SGD로 입력하세요. 총급여만 입력하면 공제 전 과세액을 가정한 추정이 됩니다.", formula: "각 누진 구간에서 해당 구간에 속하는 소득 × 구간 세율을 합산합니다. 평균세율 = 추정 세액 ÷ 입력 과세소득 ×100; 입력이 0이면 평균세율은 0입니다.", exampleNote: "과세소득 SGD 100,000이면 구간별 세액 합계는 SGD 5,650이며 평균세율은 5.65%입니다. 세액공제나 개인별 감면을 적용하기 전 계산입니다.", faq: { question: "싱가포르 비거주자에게도 이 세율이 적용되나요?", answer: "아닙니다. 이 엔진은 거주자 누진세만 계산합니다. 비거주자 고용소득과 기타 소득은 다른 규칙이 적용될 수 있습니다." } },
  },
  en: {
    "australia-gross-net-salary-calculator": { description: "Estimates Australian resident take-home pay for 2026–27 by subtracting progressive income tax and a flat 2% Medicare levy. Low-income reductions or exemptions, the Medicare levy surcharge, deductions, and non-resident rules are not assessed.", howTo: "Choose annual or monthly pay and enter gross salary. Monthly pay is multiplied by 12; review the tax and levy components separately.", formula: "Annual pay = entered pay ×12 for monthly mode. Income tax sums the configured 2026–27 resident marginal brackets; the engine estimates Medicare levy as 2% of annual pay. Net annual pay = gross annual pay − income tax − levy.", exampleNote: "AUD 80,000 annual pay gives AUD 14,520 income tax, a modeled AUD 1,600 levy, AUD 63,880 annual net, or AUD 5,323.33 per month. This is before individual reductions and deductions.", faq: { question: "Why can my payslip net pay differ?", answer: "The estimate does not assess personal deductions, levy reductions or exemptions, non-resident status, study-loan repayments, or employer withholding details." } },
    "singapore-gross-net-salary-calculator": { description: "Estimates pay using Singapore resident progressive income tax and an age-based employee CPF rate. It omits non-resident tax, reliefs, Additional Wages, and graduated CPF rates for new permanent residents.", howTo: "For the CPF component, choose monthly pay and enter gross monthly salary and age. Employer CPF is not deducted from the employee take-home result.", formula: "Monthly pay is annualized by ×12 for resident tax. Annual employee CPF = min(entered monthly pay, SGD 8,000) × the age-band employee rate ×12; estimated net subtracts tax and employee CPF from annual gross pay.", exampleNote: "At SGD 6,000 monthly pay and age 35, annual gross is SGD 72,000, estimated resident tax SGD 2,790, employee CPF SGD 14,400 per year, and net SGD 54,810 per year (SGD 4,567.50 monthly). Employer CPF is separate.", faq: { question: "Can I enter annual pay for a CPF estimate?", answer: "CPF uses monthly wages and a monthly ceiling. Use monthly mode; the annual-mode CPF component applies the monthly calculation to the raw entered amount and should not be treated as an official contribution." } },
    "singapore-income-tax-calculator": { description: "Applies Singapore's resident progressive tax bands in force from YA 2024 onward to entered annual chargeable income. Non-resident rates, personal reliefs, rebates, and tax credits are outside this estimate.", howTo: "Enter annual SGD chargeable income after relevant reliefs if known. Entering gross salary instead estimates tax before personal deductions.", formula: "For each marginal band, multiply the portion of income in that band by its rate and add the band amounts. Average rate = estimated tax ÷ entered chargeable income ×100; it is 0 when income is 0.", exampleNote: "SGD 100,000 chargeable income produces SGD 5,650 from the resident marginal bands, an average rate of 5.65%. Personal reliefs and rebates are not applied.", faq: { question: "Does this estimate cover non-residents?", answer: "No. The engine uses resident progressive bands only; non-resident employment and other income can follow different rules." } },
  },
  ja: {
    "australia-gross-net-salary-calculator": { description: "豪州居住者の2026–27年給与について、累進所得税と一律2%のMedicare levyを差し引く概算です。低所得者の減額・免除、追加課徴金、控除、非居住者規則は判定しません。", howTo: "年給または月給を選び、税引前給与を入力します。月給は12倍して年額に換算し、税とlevyの内訳を確認してください。", formula: "年収＝入力額（月給なら×12）。所得税は2026–27居住者の限界税率区分ごとに計算して合計し、Medicare levyは年収の2%とします。手取り年額＝年収−所得税−levy。", exampleNote: "年収AUD 80,000では所得税AUD 14,520、モデル上のlevy AUD 1,600、年手取りAUD 63,880（月換算AUD 5,323.33）です。個別の減免・控除前です。", faq: { question: "給与明細の手取り額と異なるのはなぜですか？", answer: "個人控除、levyの減免・免除、非居住者区分、学資ローン返済、雇用主の源泉徴収条件を判定しない概算だからです。" } },
    "singapore-gross-net-salary-calculator": { description: "シンガポール居住者の累進所得税と年齢別の従業員CPF率を使う給与概算です。非居住者税、控除、追加賃金、PR初期段階のCPF率は扱いません。", howTo: "CPFを月単位で合わせるため、月給を選び、税引前の月給と年齢を入力してください。雇用主CPFは従業員の手取りから差し引きません。", formula: "月給は×12で居住者所得税の年額計算に使います。従業員CPF年額＝min(入力月給, SGD 8,000)×年齢別率×12。推定手取りは年収から税と従業員CPFを引きます。", exampleNote: "月給SGD 6,000、35歳の場合、年収SGD 72,000、税額SGD 2,790、従業員CPF年SGD 14,400、手取り年SGD 54,810（月SGD 4,567.50）です。雇用主負担分は別です。", faq: { question: "年給入力でもCPFは正確ですか？", answer: "CPFは月給と月額上限で計算します。月給モードを使ってください。年給モードでは入力値に月次計算が適用されるため、公的な拠出額とはみなせません。" } },
    "singapore-income-tax-calculator": { description: "入力した年間課税所得にYA 2024以降のシンガポール居住者向け累進税率を適用します。非居住者税率、個人控除、還付・税額控除は含みません。", howTo: "控除後の課税所得に近い年額をSGDで入力してください。総給与を入力すると、個人控除前の概算になります。", formula: "累進区分ごとに各区分内の所得×税率を計算し合計します。平均税率＝推定税額÷入力課税所得×100。所得0の場合は0です。", exampleNote: "課税所得SGD 100,000では居住者区分の合計税額はSGD 5,650、平均税率は5.65%です。個人控除や還付前の値です。", faq: { question: "非居住者にもこの税率が適用されますか？", answer: "いいえ。この計算は居住者の累進税率のみを使います。非居住者の給与などには異なる規則が適用されます。" } },
  },
  zh: {
    "australia-gross-net-salary-calculator": { description: "按澳大利亚居民2026–27所得年度累进所得税及固定2% Medicare levy估算税后工资。不判断低收入减免或豁免、附加税、扣除及非居民规则。", howTo: "选择年薪或月薪并输入税前工资；月薪会乘以12换算成年额。请分别查看所得税和levy项目。", formula: "年收入＝输入值（月薪模式乘12）。所得税按2026–27居民边际税档分段相加；模型将Medicare levy按年收入的2%估算。年净收入＝年收入−所得税−levy。", exampleNote: "年薪AUD 80,000时，所得税AUD 14,520，模型levy AUD 1,600，年净额AUD 63,880，月均AUD 5,323.33；未计个人减免和扣除。", faq: { question: "为何与工资单实领金额不同？", answer: "本估算不判断个人扣除、levy减免或豁免、非居民身份、助学贷款偿还及雇主预扣细节。" } },
    "singapore-gross-net-salary-calculator": { description: "以新加坡居民累进所得税及按年龄划分的员工CPF费率估算工资。不包括非居民税、个人减免、额外工资及新永久居民首两年的分阶段CPF费率。", howTo: "若要估算CPF，请选择月薪并输入税前月薪和年龄。雇主CPF不会从员工实领工资中扣除。", formula: "月薪乘12用于居民年度税额。年度员工CPF＝min(输入月薪, SGD 8,000)×年龄费率×12；估算净年薪＝年毛薪−税−员工CPF。", exampleNote: "月薪SGD 6,000、35岁时，年毛薪SGD 72,000，估算税SGD 2,790，员工CPF年额SGD 14,400，净年薪SGD 54,810（月均SGD 4,567.50）。雇主份额另计。", faq: { question: "输入年薪也能准确估算CPF吗？", answer: "CPF按月工资及月度上限计算，请用月薪模式。年薪模式会把原始输入套入月度CPF公式，不能视为官方缴款额。" } },
    "singapore-income-tax-calculator": { description: "对输入的年度应税收入应用新加坡YA 2024起居民累进税率。非居民税率、个人减免、退税及税收抵免不在估算范围。", howTo: "以SGD输入年度应课税收入；若输入的是总工资，结果相当于未扣个人减免的估算。", formula: "逐级计算每个边际税档内的收入×该档税率，再相加。平均税率＝估算税额÷输入应税收入×100；收入为0时显示0。", exampleNote: "应税收入SGD 100,000按居民税档合计为SGD 5,650，平均税率5.65%。尚未应用个人减免或退税。", faq: { question: "这个结果适用于非居民吗？", answer: "不适用。引擎只计算居民累进税；非居民的雇佣收入和其他收入可能适用不同规则。" } },
  },
  es: {
    "australia-gross-net-salary-calculator": { description: "Estimación para residentes australianos en 2026–27: resta el impuesto progresivo y un Medicare levy fijo del 2%. No determina reducciones o exenciones por bajos ingresos, recargo sanitario, deducciones ni reglas de no residentes.", howTo: "Elige salario anual o mensual e introduce el bruto. El mensual se multiplica por 12; revisa por separado impuesto y levy.", formula: "Salario anual = entrada ×12 si es mensual. El impuesto suma los tramos marginales residentes 2026–27; el modelo calcula Medicare levy como 2% del salario anual. Neto anual = bruto anual − impuesto − levy.", exampleNote: "Con AUD 80.000 anuales: impuesto AUD 14.520, levy modelado AUD 1.600 y neto AUD 63.880 al año (AUD 5.323,33 al mes). Antes de reducciones y deducciones personales.", faq: { question: "¿Por qué difiere de mi nómina?", answer: "No evalúa deducciones personales, reducciones o exenciones del levy, residencia fiscal, préstamos de estudios ni detalles de retención del empleador." } },
    "singapore-gross-net-salary-calculator": { description: "Estimación salarial con impuesto progresivo de residente en Singapur y CPF del empleado según edad. Excluye impuestos de no residentes, desgravaciones, salarios adicionales y tipos escalonados para nuevos residentes permanentes.", howTo: "Para que CPF use una base mensual, selecciona pago mensual e introduce salario bruto y edad. La aportación del empleador no se resta del neto del empleado.", formula: "El salario mensual se anualiza ×12 para el impuesto de residente. CPF anual del empleado = min(salario mensual introducido, SGD 8.000) × tipo por edad ×12; el neto resta impuesto y CPF del bruto anual.", exampleNote: "Con SGD 6.000 al mes y 35 años: bruto anual SGD 72.000, impuesto estimado SGD 2.790, CPF empleado SGD 14.400 al año y neto anual SGD 54.810 (SGD 4.567,50 mensual). La parte patronal va aparte.", faq: { question: "¿Puedo introducir salario anual para calcular CPF?", answer: "CPF se basa en salarios mensuales y un límite mensual. Usa modo mensual; en modo anual la fórmula mensual se aplica al valor bruto introducido y no debe tratarse como cotización oficial." } },
    "singapore-income-tax-calculator": { description: "Aplica a la renta imponible anual introducida los tramos progresivos para residentes de Singapur vigentes desde YA 2024. No incluye tipos de no residentes, desgravaciones personales, reembolsos ni créditos fiscales.", howTo: "Introduce en SGD la renta imponible anual, idealmente después de desgravaciones conocidas. Si introduces salario bruto, será una estimación antes de ellas.", formula: "Suma la parte de renta incluida en cada tramo multiplicada por su tipo marginal. Tipo medio = impuesto estimado ÷ renta imponible introducida ×100; con renta cero es 0.", exampleNote: "Una renta imponible de SGD 100.000 produce SGD 5.650 según los tramos residentes, un tipo medio del 5,65%. No se aplican desgravaciones personales ni reembolsos.", faq: { question: "¿Sirve para personas no residentes?", answer: "No. El motor solo aplica la escala progresiva de residentes; el empleo y otros ingresos de no residentes pueden seguir reglas distintas." } },
  },
  "pt-br": {
    "australia-gross-net-salary-calculator": { description: "Estimativa para residentes australianos em 2026–27: subtrai o imposto progressivo e um Medicare levy fixo de 2%. Não verifica redução ou isenção para baixa renda, sobretaxa de saúde, deduções nem regras de não residentes.", howTo: "Escolha salário anual ou mensal e informe o valor bruto. O mensal é multiplicado por 12; confira separadamente imposto e levy.", formula: "Salário anual = entrada ×12 no modo mensal. O imposto soma as faixas marginais de residentes 2026–27; o modelo calcula Medicare levy como 2% do salário anual. Líquido anual = bruto anual − imposto − levy.", exampleNote: "Com AUD 80.000 por ano: imposto AUD 14.520, levy modelado AUD 1.600 e líquido AUD 63.880 anuais (AUD 5.323,33 por mês). Antes de reduções e deduções pessoais.", faq: { question: "Por que o valor difere do contracheque?", answer: "A estimativa não avalia deduções pessoais, redução ou isenção do levy, residência fiscal, empréstimo estudantil nem detalhes de retenção do empregador." } },
    "singapore-gross-net-salary-calculator": { description: "Estimativa salarial usando o imposto progressivo de residente de Singapura e o CPF do empregado por faixa etária. Não inclui imposto de não residente, abatimentos, salários adicionais ou taxas graduais de novos residentes permanentes.", howTo: "Para calcular CPF sobre uma base mensal, escolha frequência mensal e informe salário bruto e idade. O CPF do empregador não é descontado do líquido do empregado.", formula: "O salário mensal é anualizado ×12 para o imposto de residente. CPF anual do empregado = min(salário mensal informado, SGD 8.000) × taxa por idade ×12; o líquido subtrai imposto e CPF do bruto anual.", exampleNote: "Com SGD 6.000 mensais e 35 anos: bruto anual SGD 72.000, imposto estimado SGD 2.790, CPF do empregado SGD 14.400 por ano e líquido SGD 54.810 (SGD 4.567,50 mensais). A parcela patronal é separada.", faq: { question: "Posso informar salário anual para estimar CPF?", answer: "O CPF usa salários e teto mensais. Use o modo mensal; no modo anual a fórmula mensal é aplicada ao valor bruto informado e não representa uma contribuição oficial." } },
    "singapore-income-tax-calculator": { description: "Aplica as faixas progressivas para residentes de Singapura, vigentes desde YA 2024, à renda tributável anual informada. Exclui taxas de não residentes, abatimentos pessoais, reembolsos e créditos fiscais.", howTo: "Informe em SGD a renda tributável anual, de preferência após abatimentos conhecidos. Se informar o salário bruto, o cálculo será antes deles.", formula: "Some a parcela da renda em cada faixa multiplicada pela respectiva taxa marginal. Taxa média = imposto estimado ÷ renda tributável informada ×100; renda zero resulta em 0.", exampleNote: "Renda tributável de SGD 100.000 resulta em SGD 5.650 pelas faixas de residentes, taxa média de 5,65%. Abatimentos pessoais e reembolsos não são aplicados.", faq: { question: "O resultado vale para não residentes?", answer: "Não. O motor usa apenas a tabela progressiva de residentes; emprego e outras rendas de não residentes podem seguir regras diferentes." } },
  },
  de: {
    "australia-gross-net-salary-calculator": { description: "Schätzung für australische Steueransässige 2026–27: progressive Einkommensteuer und eine pauschale Medicare levy von 2 % werden abgezogen. Niedrigeinkommensminderung, Befreiung, Zuschlag, Abzüge und Nichtansässigenregeln werden nicht geprüft.", howTo: "Wähle Jahres- oder Monatsgehalt und gib den Bruttobetrag ein. Monatsgehalt wird mit 12 multipliziert; Steuer und levy separat prüfen.", formula: "Jahresgehalt = Eingabe ×12 bei Monatsmodus. Die Steuer summiert die residenten Grenzsteuersätze 2026–27; die levy wird im Modell mit 2 % des Jahresgehalts angesetzt. Netto = Brutto − Steuer − levy.", exampleNote: "Bei AUD 80.000 Jahresgehalt: AUD 14.520 Einkommensteuer, modellierte levy AUD 1.600, netto AUD 63.880 jährlich (AUD 5.323,33 monatlich). Persönliche Ermäßigungen und Abzüge fehlen.", faq: { question: "Warum weicht das Ergebnis von der Gehaltsabrechnung ab?", answer: "Persönliche Abzüge, levy-Ermäßigungen oder Befreiungen, Steuerwohnsitz, Studienkredit und konkrete Lohnsteuerabzüge werden nicht bewertet." } },
    "singapore-gross-net-salary-calculator": { description: "Gehaltschätzung mit progressiver Einkommensteuer für Ansässige in Singapur und altersabhängigem Arbeitnehmer-CPF. Nichtansässigensteuer, persönliche Entlastungen, Zusatzlohn und gestaffelte CPF-Sätze neuer PR sind ausgeschlossen.", howTo: "Für eine monatliche CPF-Basis Monatslohn wählen und Bruttogehalt sowie Alter eingeben. Der Arbeitgeberanteil wird nicht vom Nettogehalt des Beschäftigten abgezogen.", formula: "Monatslohn wird für die residenten Steuer mit ×12 annualisiert. Jährliches Arbeitnehmer-CPF = min(eingegebener Monatslohn, 8.000 SGD) × Altersrate ×12; vom Jahresbrutto werden Steuer und Arbeitnehmer-CPF abgezogen.", exampleNote: "Bei 6.000 SGD Monatslohn und Alter 35: Jahresbrutto 72.000 SGD, geschätzte Steuer 2.790 SGD, Arbeitnehmer-CPF 14.400 SGD jährlich und netto 54.810 SGD (4.567,50 SGD monatlich). Arbeitgeberbeitrag separat.", faq: { question: "Kann ich Jahresgehalt für CPF eingeben?", answer: "CPF richtet sich nach Monatslohn und Monatsgrenze. Monatsmodus verwenden; im Jahresmodus wird die Monatsformel auf den Rohwert angewandt und ist kein offizieller Beitragsbetrag." } },
    "singapore-income-tax-calculator": { description: "Wendet die progressiven Einkommensteuerstufen für Ansässige in Singapur ab YA 2024 auf das eingegebene jährliche steuerpflichtige Einkommen an. Nichtansässigensteuern, persönliche Entlastungen, Erstattungen und Steuergutschriften fehlen.", howTo: "Jährliches steuerpflichtiges Einkommen in SGD eingeben, möglichst nach bekannten Entlastungen. Bruttogehalt ergibt eine Schätzung vor persönlichen Abzügen.", formula: "Für jede Grenzstufe wird der darin liegende Einkommensteil mit dem Satz multipliziert und addiert. Durchschnittssatz = geschätzte Steuer ÷ eingegebenes Einkommen ×100; bei 0 Einkommen ist er 0.", exampleNote: "100.000 SGD steuerpflichtiges Einkommen ergeben nach residenten Stufen 5.650 SGD Steuer und einen Durchschnittssatz von 5,65 %. Persönliche Entlastungen und Erstattungen fehlen.", faq: { question: "Gilt die Schätzung für Nichtansässige?", answer: "Nein. Der Rechner nutzt nur die residenten Progressionsstufen; Beschäftigungs- und andere Einkünfte Nichtansässiger können anders besteuert werden." } },
  },
  fr: {
    "australia-gross-net-salary-calculator": { description: "Estimation pour les résidents australiens en 2026–27 : elle déduit l’impôt progressif et un Medicare levy forfaitaire de 2 %. Les réductions ou exonérations modestes, surtaxe, déductions et règles des non-résidents ne sont pas évaluées.", howTo: "Choisissez un salaire annuel ou mensuel et saisissez le brut. Le montant mensuel est multiplié par 12 ; examinez séparément impôt et levy.", formula: "Salaire annuel = saisie ×12 en mode mensuel. L’impôt additionne les tranches marginales résidentes 2026–27 ; le modèle fixe le Medicare levy à 2 % du salaire annuel. Net annuel = brut − impôt − levy.", exampleNote: "Pour 80 000 AUD annuels : impôt 14 520 AUD, levy modélisé 1 600 AUD et net annuel 63 880 AUD (5 323,33 AUD par mois). Réductions et déductions personnelles exclues.", faq: { question: "Pourquoi le résultat diffère-t-il de ma fiche de paie ?", answer: "Les déductions, réductions ou exonérations du levy, la résidence fiscale, le prêt étudiant et les retenues propres à l’employeur ne sont pas évalués." } },
    "singapore-gross-net-salary-calculator": { description: "Estimation salariale avec l’impôt progressif des résidents de Singapour et le taux CPF salarié selon l’âge. Impôt des non-résidents, allègements, salaires supplémentaires et taux progressifs des nouveaux PR exclus.", howTo: "Pour une base CPF mensuelle, sélectionnez la paie mensuelle et saisissez salaire brut et âge. La part CPF de l’employeur n’est pas déduite du net salarié.", formula: "Le salaire mensuel est annualisé ×12 pour l’impôt résident. CPF annuel salarié = min(salaire mensuel saisi, 8 000 SGD) × taux d’âge ×12 ; le net retire impôt et CPF salarié du brut annuel.", exampleNote: "Avec 6 000 SGD par mois et 35 ans : brut annuel 72 000 SGD, impôt estimé 2 790 SGD, CPF salarié 14 400 SGD/an et net annuel 54 810 SGD (4 567,50 SGD/mois). Part patronale séparée.", faq: { question: "Puis-je saisir un salaire annuel pour CPF ?", answer: "CPF dépend des salaires mensuels et d’un plafond mensuel. Utilisez le mode mensuel ; en mode annuel, la formule mensuelle est appliquée à la valeur brute et ne vaut pas cotisation officielle." } },
    "singapore-income-tax-calculator": { description: "Applique au revenu imposable annuel saisi les tranches progressives des résidents de Singapour en vigueur depuis YA 2024. Taux des non-résidents, allègements personnels, remboursements et crédits exclus.", howTo: "Saisissez en SGD le revenu imposable annuel, idéalement après les allègements connus. Un salaire brut donne une estimation avant ceux-ci.", formula: "Pour chaque tranche marginale, multipliez la part de revenu concernée par son taux puis additionnez. Taux moyen = impôt estimé ÷ revenu saisi ×100 ; il vaut 0 si le revenu est nul.", exampleNote: "Un revenu imposable de 100 000 SGD donne 5 650 SGD selon les tranches résidentes, soit 5,65 % en moyenne. Aucun allègement personnel ni remboursement n’est appliqué.", faq: { question: "Ce résultat s’applique-t-il aux non-résidents ?", answer: "Non. Le moteur utilise seulement les tranches progressives résidentes ; les revenus professionnels et autres des non-résidents peuvent relever d’autres règles." } },
  },
  vi: {
    "australia-gross-net-salary-calculator": { description: "Ước tính lương thực nhận của cư dân Australia năm 2026–27 bằng thuế lũy tiến và Medicare levy cố định 2%. Không xét giảm hoặc miễn levy cho thu nhập thấp, phụ thu, khấu trừ hay quy tắc người không cư trú.", howTo: "Chọn lương năm hoặc tháng rồi nhập lương trước thuế. Lương tháng được nhân 12; hãy xem riêng thuế và levy.", formula: "Lương năm = số nhập ×12 nếu chọn tháng. Thuế cộng các phần thu nhập theo bậc biên dành cho cư dân 2026–27; mô hình tính levy bằng 2% lương năm. Lương ròng năm = lương gộp − thuế − levy.", exampleNote: "Lương năm AUD 80.000 cho thuế AUD 14.520, levy mô hình AUD 1.600 và ròng năm AUD 63.880 (AUD 5.323,33/tháng), trước các giảm trừ cá nhân.", faq: { question: "Vì sao khác với tiền thực nhận trên phiếu lương?", answer: "Ước tính không xét khấu trừ cá nhân, giảm hoặc miễn levy, tình trạng cư trú thuế, khoản vay học tập hay cách khấu lưu cụ thể của chủ lao động." } },
    "singapore-gross-net-salary-calculator": { description: "Ước tính lương theo thuế lũy tiến cư dân Singapore và tỷ lệ CPF nhân viên theo tuổi. Không gồm thuế người không cư trú, khoản giảm thuế, lương bổ sung hay mức CPF bậc thang cho PR mới.", howTo: "Để CPF dùng đúng cơ sở tháng, chọn lương tháng và nhập lương gộp cùng tuổi. Phần CPF của chủ lao động không bị trừ khỏi lương ròng nhân viên.", formula: "Lương tháng nhân 12 để tính thuế cư dân theo năm. CPF nhân viên năm = min(lương tháng đã nhập, SGD 8.000) × tỷ lệ theo tuổi ×12; lương ròng trừ thuế và CPF nhân viên khỏi lương năm.", exampleNote: "Lương SGD 6.000/tháng, tuổi 35: gộp năm SGD 72.000, thuế ước tính SGD 2.790, CPF nhân viên SGD 14.400/năm và ròng SGD 54.810/năm (SGD 4.567,50/tháng). Phần chủ lao động riêng.", faq: { question: "Có thể nhập lương năm để tính CPF không?", answer: "CPF dựa trên lương và trần theo tháng. Hãy dùng chế độ tháng; chế độ năm áp dụng công thức tháng lên số nhập thô nên không phải khoản đóng chính thức." } },
    "singapore-income-tax-calculator": { description: "Áp dụng các bậc thuế lũy tiến cho cư dân Singapore từ YA 2024 lên thu nhập chịu thuế năm đã nhập. Không gồm thuế người không cư trú, giảm trừ cá nhân, hoàn thuế hoặc tín thuế.", howTo: "Nhập thu nhập chịu thuế năm bằng SGD, tốt nhất sau các khoản giảm trừ đã biết. Nếu nhập lương gộp, kết quả là trước giảm trừ cá nhân.", formula: "Với từng bậc biên, nhân phần thu nhập nằm trong bậc với thuế suất rồi cộng lại. Thuế suất trung bình = thuế ước tính ÷ thu nhập nhập vào ×100; bằng 0 khi thu nhập bằng 0.", exampleNote: "Thu nhập chịu thuế SGD 100.000 cho thuế SGD 5.650 theo bậc cư dân, mức trung bình 5,65%. Chưa áp dụng giảm trừ hoặc hoàn thuế cá nhân.", faq: { question: "Kết quả này có áp dụng cho người không cư trú không?", answer: "Không. Công cụ chỉ dùng biểu thuế lũy tiến cư dân; thu nhập lao động và thu nhập khác của người không cư trú có thể theo quy tắc riêng." } },
  },
  id: {
    "australia-gross-net-salary-calculator": { description: "Perkiraan gaji bersih penduduk Australia tahun 2026–27 setelah pajak progresif dan Medicare levy tetap 2%. Pengurangan atau pembebasan berpenghasilan rendah, surcharge, pengurang pajak, dan aturan nonresiden tidak dinilai.", howTo: "Pilih gaji tahunan atau bulanan lalu masukkan nilai bruto. Gaji bulanan dikalikan 12; periksa pajak dan levy secara terpisah.", formula: "Gaji tahunan = nilai masukan ×12 untuk mode bulanan. Pajak menjumlahkan lapisan marginal residen 2026–27; model memakai Medicare levy 2% dari gaji tahunan. Bersih tahunan = bruto − pajak − levy.", exampleNote: "Gaji AUD 80.000 per tahun menghasilkan pajak AUD 14.520, levy model AUD 1.600, dan bersih AUD 63.880 per tahun (AUD 5.323,33 per bulan), sebelum pengurangan pribadi.", faq: { question: "Mengapa berbeda dari slip gaji?", answer: "Perkiraan tidak menilai pengurang pribadi, pengurangan atau pembebasan levy, status residensi pajak, pinjaman pendidikan, atau pemotongan oleh pemberi kerja." } },
    "singapore-gross-net-salary-calculator": { description: "Perkiraan gaji dengan pajak progresif residen Singapura dan CPF karyawan menurut usia. Pajak nonresiden, keringanan pribadi, upah tambahan, dan tarif bertahap CPF untuk PR baru tidak dihitung.", howTo: "Agar basis CPF bulanan sesuai, pilih pembayaran bulanan dan masukkan gaji bruto serta usia. CPF pemberi kerja tidak dikurangkan dari take-home karyawan.", formula: "Gaji bulanan dikalikan 12 untuk pajak tahunan residen. CPF karyawan tahunan = min(gaji bulanan yang dimasukkan, SGD 8.000) × tarif usia ×12; take-home mengurangi pajak dan CPF karyawan dari gaji tahunan.", exampleNote: "Gaji SGD 6.000/bulan, usia 35: bruto tahunan SGD 72.000, pajak perkiraan SGD 2.790, CPF karyawan SGD 14.400/tahun, bersih SGD 54.810/tahun (SGD 4.567,50/bulan). Bagian pemberi kerja terpisah.", faq: { question: "Bolehkah memasukkan gaji tahunan untuk CPF?", answer: "CPF memakai upah dan batas bulanan. Gunakan mode bulanan; mode tahunan menerapkan rumus bulanan ke nilai mentah dan bukan jumlah kontribusi resmi." } },
    "singapore-income-tax-calculator": { description: "Menerapkan tarif progresif residen Singapura sejak YA 2024 pada penghasilan kena pajak tahunan yang dimasukkan. Tarif nonresiden, keringanan pribadi, pengembalian, dan kredit pajak tidak termasuk.", howTo: "Masukkan penghasilan kena pajak tahunan dalam SGD, idealnya setelah keringanan yang diketahui. Gaji bruto berarti estimasi sebelum keringanan pribadi.", formula: "Kalikan bagian penghasilan di setiap lapisan marginal dengan tarifnya lalu jumlahkan. Tarif rata-rata = pajak perkiraan ÷ penghasilan yang dimasukkan ×100; nol bila penghasilan nol.", exampleNote: "Penghasilan kena pajak SGD 100.000 menghasilkan pajak SGD 5.650 menurut lapisan residen, rata-rata 5,65%. Keringanan pribadi dan pengembalian belum diterapkan.", faq: { question: "Apakah hasil ini berlaku untuk nonresiden?", answer: "Tidak. Mesin hanya memakai lapisan progresif residen; penghasilan kerja dan jenis penghasilan nonresiden lain dapat mengikuti aturan berbeda." } },
  },
  th: {
    "australia-gross-net-salary-calculator": { description: "ประมาณเงินเดือนสุทธิของผู้มีถิ่นที่อยู่ในออสเตรเลียปี 2026–27 หลังหักภาษีก้าวหน้าและ Medicare levy คงที่ 2% ไม่ตรวจการลดหรือยกเว้นสำหรับรายได้น้อย ค่าธรรมเนียมเพิ่ม รายการหัก หรือกฎผู้ไม่มีถิ่นที่อยู่", howTo: "เลือกรายปีหรือรายเดือนแล้วกรอกเงินเดือนก่อนหักภาษี เงินรายเดือนคูณ 12 และตรวจดูภาษีกับ levy แยกกัน", formula: "รายได้ต่อปี = ค่าที่กรอก ×12 เมื่อเลือกรายเดือน ภาษีรวมส่วนที่อยู่ในแต่ละขั้นอัตราส่วนเพิ่มของผู้มีถิ่นที่อยู่ปี 2026–27; แบบจำลองคิด levy 2% ของรายได้ปี รายได้สุทธิ = รายได้รวม−ภาษี−levy", exampleNote: "เงินเดือน AUD 80,000 ต่อปีได้ภาษี AUD 14,520, levy ตามแบบจำลอง AUD 1,600 และสุทธิ AUD 63,880 ต่อปี (AUD 5,323.33 ต่อเดือน) ก่อนสิทธิลดหย่อนส่วนบุคคล", faq: { question: "ทำไมยอดจึงต่างจากสลิปเงินเดือน?", answer: "ไม่ได้ประเมินรายการหักส่วนบุคคล การลดหรือยกเว้น levy สถานะผู้มีถิ่นที่อยู่ เงินกู้เพื่อการศึกษา หรือรายละเอียดการหัก ณ ที่จ่ายของนายจ้าง" } },
    "singapore-gross-net-salary-calculator": { description: "ประมาณเงินเดือนด้วยภาษีก้าวหน้าสำหรับผู้มีถิ่นที่อยู่ในสิงคโปร์และอัตรา CPF ลูกจ้างตามอายุ ไม่รวมภาษีผู้ไม่มีถิ่นที่อยู่ ค่าลดหย่อน เงินเดือนเพิ่มเติม และอัตรา CPF ขั้นบันไดของ PR ใหม่", howTo: "เพื่อให้ฐาน CPF เป็นรายเดือน เลือกความถี่รายเดือนแล้วกรอกเงินเดือนก่อนหักและอายุ CPF ฝั่งนายจ้างไม่ถูกหักจากเงินสุทธิลูกจ้าง", formula: "เงินรายเดือนคูณ 12 เพื่อคำนวณภาษีรายปี CPF ลูกจ้างต่อปี = min(เงินเดือนรายเดือนที่กรอก, SGD 8,000) × อัตราตามอายุ ×12; เงินสุทธิหักภาษีและ CPF ลูกจ้างจากเงินเดือนรายปี", exampleNote: "เงินเดือน SGD 6,000 ต่อเดือน อายุ 35 ปี: รายได้ปี SGD 72,000 ภาษีประมาณ SGD 2,790 CPF ลูกจ้าง SGD 14,400/ปี และสุทธิ SGD 54,810/ปี (SGD 4,567.50/เดือน) ส่วนของนายจ้างแยกต่างหาก", faq: { question: "กรอกเงินเดือนรายปีเพื่อคำนวณ CPF ได้ไหม?", answer: "CPF ใช้ค่าจ้างและเพดานรายเดือน โปรดเลือกรายเดือน; โหมดรายปีนำสูตรรายเดือนไปใช้กับค่าดิบ จึงไม่ใช่ยอดเงินสมทบทางการ" } },
    "singapore-income-tax-calculator": { description: "ใช้ขั้นภาษีก้าวหน้าสำหรับผู้มีถิ่นที่อยู่ในสิงคโปร์ซึ่งใช้ตั้งแต่ YA 2024 กับรายได้พึงประเมินต่อปี ไม่รวมอัตราผู้ไม่มีถิ่นที่อยู่ ค่าลดหย่อนส่วนบุคคล เงินคืนหรือเครดิตภาษี", howTo: "กรอกรายได้พึงประเมินรายปีเป็น SGD โดยหักค่าลดหย่อนที่ทราบแล้ว หากกรอกเงินเดือนรวม ผลจะเป็นค่าประมาณก่อนค่าลดหย่อน", formula: "คูณรายได้ส่วนที่อยู่ในแต่ละขั้นด้วยอัตราส่วนเพิ่ม แล้วรวมกัน อัตราเฉลี่ย = ภาษีประมาณ ÷ รายได้ที่กรอก ×100; เป็น 0 เมื่อรายได้เป็น 0", exampleNote: "รายได้พึงประเมิน SGD 100,000 ได้ภาษี SGD 5,650 ตามขั้นของผู้มีถิ่นที่อยู่ อัตราเฉลี่ย 5.65% ยังไม่ใช้ค่าลดหย่อนหรือเงินคืนส่วนบุคคล", faq: { question: "ใช้กับผู้ไม่มีถิ่นที่อยู่ได้หรือไม่?", answer: "ไม่ได้ เครื่องคำนวณใช้เฉพาะขั้นภาษีของผู้มีถิ่นที่อยู่; รายได้จ้างงานและรายได้อื่นของผู้ไม่มีถิ่นที่อยู่อาจมีกฎต่างกัน" } },
  },
  "zh-tw": {
    "australia-gross-net-salary-calculator": { description: "以澳洲居民 2026–27 所得年度的累進所得稅及固定 2% Medicare levy 估算稅後薪資。不判斷低收入減免或豁免、附加稅、扣除額及非居民規則。", howTo: "選擇年薪或月薪並輸入稅前金額；月薪會乘 12 換算成年額，請分別查看稅與 levy。", formula: "年收入＝輸入值（月薪模式乘 12）。所得稅按 2026–27 居民邊際稅級分段加總；模型將 Medicare levy 設為年收入的 2%。年淨額＝年毛額−所得稅−levy。", exampleNote: "年薪 AUD 80,000 得所得稅 AUD 14,520、模型 levy AUD 1,600，年淨額 AUD 63,880（月均 AUD 5,323.33）；尚未計個人減免與扣除。", faq: { question: "為何與薪資單實領金額不同？", answer: "此估算未判斷個人扣除、levy 減免或豁免、稅務居留身分、學貸還款及雇主預扣細節。" } },
    "singapore-gross-net-salary-calculator": { description: "以新加坡居民累進所得稅及依年齡區分的員工 CPF 費率估算薪資。不含非居民稅、個人減免、額外工資及新永久居民的分階段 CPF 費率。", howTo: "CPF 採月薪基礎，請選月薪並輸入稅前月薪與年齡。雇主 CPF 不會從員工實領薪資扣除。", formula: "月薪乘 12 換算成年額供居民所得稅使用。年度員工 CPF＝min(輸入月薪, SGD 8,000)×年齡費率×12；淨年薪從年毛薪扣除稅與員工 CPF。", exampleNote: "月薪 SGD 6,000、35 歲：年毛薪 SGD 72,000、估算稅 SGD 2,790、員工 CPF 年額 SGD 14,400、年淨額 SGD 54,810（月 SGD 4,567.50）。雇主提撥另計。", faq: { question: "輸入年薪也能準確估算 CPF 嗎？", answer: "CPF 依月薪及月上限計算，請用月薪模式；年薪模式會把原始輸入套入月計公式，不能視為官方提撥額。" } },
    "singapore-income-tax-calculator": { description: "將 YA 2024 起的新加坡居民累進稅率套用於輸入的年度應稅所得。不含非居民稅率、個人減免、退稅及稅額抵免。", howTo: "以 SGD 輸入年度應課稅所得，最好先扣除已知減免；若輸入總薪資，結果是扣除前估算。", formula: "逐級計算每個邊際稅級中的所得部分乘以該級稅率後加總。平均稅率＝估算稅額÷輸入所得×100；所得為 0 時為 0。", exampleNote: "應稅所得 SGD 100,000 按居民級距得稅額 SGD 5,650，平均稅率 5.65%；尚未套用個人減免或退稅。", faq: { question: "非居民也適用這個結果嗎？", answer: "不適用。引擎只計算居民累進稅；非居民的受僱所得及其他所得可能適用不同規則。" } },
  },
  it: {
    "australia-gross-net-salary-calculator": { description: "Stima per residenti australiani nel 2026–27: sottrae l’imposta progressiva e un Medicare levy fisso del 2%. Non valuta riduzioni o esenzioni per redditi bassi, surcharge, detrazioni né regole per non residenti.", howTo: "Scegli stipendio annuale o mensile e inserisci il lordo. Il mensile viene moltiplicato per 12; controlla separatamente imposta e levy.", formula: "Reddito annuo = input ×12 in modalità mensile. L’imposta somma gli scaglioni marginali residenti 2026–27; il modello stima il Medicare levy al 2% del reddito annuo. Netto annuo = lordo − imposta − levy.", exampleNote: "Con AUD 80.000 annui: imposta AUD 14.520, levy modellato AUD 1.600, netto AUD 63.880 annui (AUD 5.323,33 mensili), prima di riduzioni e detrazioni personali.", faq: { question: "Perché differisce dalla busta paga?", answer: "La stima non valuta detrazioni personali, riduzioni o esenzioni del levy, residenza fiscale, prestiti di studio o dettagli delle ritenute del datore." } },
    "singapore-gross-net-salary-calculator": { description: "Stima dello stipendio con imposta progressiva per residenti di Singapore e CPF del dipendente in base all’età. Esclude imposte per non residenti, agevolazioni, salari aggiuntivi e aliquote CPF graduali per nuovi PR.", howTo: "Per una base CPF mensile scegli la frequenza mensile e inserisci stipendio lordo ed età. La quota CPF del datore non viene sottratta dal netto del dipendente.", formula: "Lo stipendio mensile è annualizzato ×12 per l’imposta residente. CPF annuo del dipendente = min(stipendio mensile inserito, SGD 8.000) × aliquota per età ×12; il netto sottrae imposta e CPF dipendente dal lordo annuo.", exampleNote: "Con SGD 6.000 mensili ed età 35: lordo annuo SGD 72.000, imposta stimata SGD 2.790, CPF dipendente SGD 14.400/anno e netto SGD 54.810 (SGD 4.567,50 al mese). Quota datore separata.", faq: { question: "Posso inserire uno stipendio annuo per CPF?", answer: "CPF usa salari e massimale mensili. Seleziona mensile; in modalità annuale la formula mensile è applicata al valore grezzo e non è un contributo ufficiale." } },
    "singapore-income-tax-calculator": { description: "Applica al reddito imponibile annuo inserito le aliquote progressive per residenti di Singapore valide da YA 2024. Esclude aliquote per non residenti, agevolazioni personali, rimborsi e crediti d’imposta.", howTo: "Inserisci in SGD il reddito imponibile annuo, possibilmente dopo le agevolazioni note. Il reddito lordo produce una stima prima delle detrazioni personali.", formula: "Per ogni scaglione marginale moltiplica la parte di reddito pertinente per l’aliquota e somma i risultati. Aliquota media = imposta stimata ÷ reddito inserito ×100; è 0 con reddito nullo.", exampleNote: "Un reddito imponibile di SGD 100.000 produce SGD 5.650 secondo gli scaglioni residenti, con media del 5,65%. Agevolazioni personali e rimborsi non sono applicati.", faq: { question: "Il risultato vale per i non residenti?", answer: "No. Il motore applica solo gli scaglioni progressivi residenti; redditi di lavoro e altri redditi dei non residenti possono seguire regole diverse." } },
  },
  nl: {
    "australia-gross-net-salary-calculator": { description: "Schatting voor Australische inwoners in 2026–27: progressieve inkomstenbelasting en een vaste Medicare levy van 2% worden afgetrokken. Lage-inkomensverlaging of vrijstelling, toeslag, aftrekposten en regels voor niet-inwoners worden niet beoordeeld.", howTo: "Kies jaar- of maandsalaris en voer het brutobedrag in. Maandsalaris wordt met 12 vermenigvuldigd; bekijk belasting en levy apart.", formula: "Jaarinkomen = invoer ×12 bij maandmodus. De belasting telt de residentiële marginale schijven 2026–27 op; het model rekent Medicare levy als 2% van jaarinkomen. Netto jaar = bruto − belasting − levy.", exampleNote: "Bij AUD 80.000 per jaar: belasting AUD 14.520, gemodelleerde levy AUD 1.600 en netto AUD 63.880 per jaar (AUD 5.323,33 per maand), vóór persoonlijke verlagingen en aftrek.", faq: { question: "Waarom wijkt dit af van mijn loonstrook?", answer: "Persoonlijke aftrek, levy-verlaging of vrijstelling, fiscale woonplaats, studielening en inhoudingsdetails van de werkgever worden niet beoordeeld." } },
    "singapore-gross-net-salary-calculator": { description: "Schat salaris met progressieve inwonerbelasting in Singapore en werknemers-CPF naar leeftijd. Niet-inwonerbelasting, persoonlijke tegemoetkomingen, extra loon en getrapte CPF-tarieven voor nieuwe PR zijn uitgesloten.", howTo: "Kies maandloon om CPF op maandbasis te benaderen en voer bruto salaris en leeftijd in. Werkgevers-CPF wordt niet van het nettoloon van de werknemer afgetrokken.", formula: "Maandloon wordt ×12 geannualiseerd voor inwonerbelasting. Jaarlijks werknemers-CPF = min(ingevoerd maandloon, SGD 8.000) × leeftijdstarief ×12; netto trekt belasting en werknemers-CPF af van bruto jaarloon.", exampleNote: "Bij SGD 6.000 per maand en leeftijd 35: bruto jaarloon SGD 72.000, belasting SGD 2.790, werknemers-CPF SGD 14.400 per jaar en netto SGD 54.810 (SGD 4.567,50 per maand). Werkgeversdeel staat apart.", faq: { question: "Kan ik jaarloon invoeren voor CPF?", answer: "CPF gebruikt maandlonen en een maandgrens. Kies maandmodus; jaarmodus past de maandformule toe op de ruwe invoer en is geen officieel bijdragebedrag." } },
    "singapore-income-tax-calculator": { description: "Past de progressieve inwonertarieven van Singapore vanaf YA 2024 toe op ingevoerd jaarlijks belastbaar inkomen. Tarieven voor niet-inwoners, persoonlijke tegemoetkomingen, teruggaven en belastingkredieten ontbreken.", howTo: "Voer jaarlijks belastbaar inkomen in SGD in, bij voorkeur na bekende tegemoetkomingen. Brutosalaris geeft een schatting vóór persoonlijke aftrek.", formula: "Vermenigvuldig het inkomensdeel in elke marginale schijf met het tarief en tel de bedragen op. Gemiddeld tarief = geschatte belasting ÷ ingevoerd inkomen ×100; bij nul inkomen is dit 0.", exampleNote: "SGD 100.000 belastbaar inkomen geeft SGD 5.650 volgens inwonerschijven, gemiddeld 5,65%. Persoonlijke tegemoetkomingen en teruggaven zijn niet toegepast.", faq: { question: "Geldt dit ook voor niet-inwoners?", answer: "Nee. De engine gebruikt alleen de progressieve inwonerschijven; arbeids- en ander inkomen van niet-inwoners kan andere regels volgen." } },
  },
  hi: {
    "australia-gross-net-salary-calculator": { description: "2026–27 में ऑस्ट्रेलियाई कर-निवासी के लिए प्रगतिशील आयकर और स्थिर 2% Medicare levy घटाकर अनुमान देता है। कम आय की छूट/कमी, surcharge, कटौतियाँ और गैर-निवासी नियम नहीं जाँचे जाते।", howTo: "वार्षिक या मासिक वेतन चुनकर सकल वेतन भरें। मासिक रकम को 12 से गुणा किया जाता है; कर और levy अलग देखें।", formula: "वार्षिक वेतन = मासिक मोड में दर्ज रकम ×12। कर 2026–27 निवासी सीमांत स्लैब का योग है; मॉडल Medicare levy को वार्षिक वेतन का 2% मानता है। शुद्ध वार्षिक = सकल − कर − levy।", exampleNote: "AUD 80,000 वार्षिक पर आयकर AUD 14,520, मॉडल levy AUD 1,600 और शुद्ध AUD 63,880 वार्षिक (AUD 5,323.33 मासिक) है; व्यक्तिगत राहत/कटौती से पहले।", faq: { question: "यह पेस्लिप से अलग क्यों हो सकता है?", answer: "व्यक्तिगत कटौती, levy राहत या छूट, कर-निवास, शिक्षा ऋण और नियोक्ता की withholding व्यवस्था का आकलन नहीं होता।" } },
    "singapore-gross-net-salary-calculator": { description: "सिंगापुर निवासी की प्रगतिशील आयकर दरों और आयु-आधारित कर्मचारी CPF से वेतन का अनुमान है। गैर-निवासी कर, व्यक्तिगत राहत, अतिरिक्त वेतन और नए PR की चरणबद्ध CPF दरें शामिल नहीं हैं।", howTo: "CPF के मासिक आधार के लिए मासिक वेतन चुनें और सकल वेतन तथा आयु भरें। नियोक्ता CPF कर्मचारी की take-home रकम से नहीं घटता।", formula: "मासिक वेतन को निवासी कर के लिए ×12 वार्षिक किया जाता है। वार्षिक कर्मचारी CPF = min(दर्ज मासिक वेतन, SGD 8,000) × आयु दर ×12; शुद्ध रकम से कर और कर्मचारी CPF घटते हैं।", exampleNote: "SGD 6,000 मासिक और आयु 35 पर वार्षिक सकल SGD 72,000, अनुमानित कर SGD 2,790, कर्मचारी CPF SGD 14,400/वर्ष और शुद्ध SGD 54,810/वर्ष (SGD 4,567.50/माह) है। नियोक्ता हिस्सा अलग है।", faq: { question: "क्या CPF के लिए वार्षिक वेतन दर्ज कर सकता हूँ?", answer: "CPF मासिक वेतन और सीमा पर आधारित है। मासिक मोड चुनें; वार्षिक मोड कच्ची रकम पर मासिक सूत्र लगाता है, इसलिए उसे आधिकारिक योगदान न मानें।" } },
    "singapore-income-tax-calculator": { description: "YA 2024 से लागू सिंगापुर निवासी प्रगतिशील दरों को दर्ज वार्षिक करयोग्य आय पर लागू करता है। गैर-निवासी दरें, व्यक्तिगत राहत, रिफंड और कर क्रेडिट शामिल नहीं हैं।", howTo: "ज्ञात राहत के बाद की वार्षिक करयोग्य आय SGD में भरें। सकल वेतन भरने पर परिणाम व्यक्तिगत राहत से पहले का अनुमान है।", formula: "हर सीमांत स्लैब में आने वाली आय को उसकी दर से गुणा कर जोड़ें। औसत दर = अनुमानित कर ÷ दर्ज करयोग्य आय ×100; शून्य आय पर 0।", exampleNote: "SGD 100,000 करयोग्य आय पर निवासी स्लैब से कर SGD 5,650 और औसत दर 5.65% है। व्यक्तिगत राहत और रिफंड लागू नहीं हैं।", faq: { question: "क्या यह गैर-निवासियों पर लागू है?", answer: "नहीं। इंजन केवल निवासी प्रगतिशील स्लैब उपयोग करता है; गैर-निवासियों के रोजगार या अन्य आय पर अलग नियम हो सकते हैं।" } },
  },
  ru: {
    "australia-gross-net-salary-calculator": { description: "Оценка для налоговых резидентов Австралии за 2026–27 год: прогрессивный подоходный налог и фиксированный Medicare levy 2%. Льготы для низкого дохода, освобождения, надбавка, вычеты и правила нерезидентов не проверяются.", howTo: "Выберите годовую или месячную зарплату и введите сумму до вычетов. Месячная сумма умножается на 12; налог и levy показаны отдельно.", formula: "Годовой доход = ввод ×12 в месячном режиме. Налог — сумма по предельным ставкам резидентов 2026–27; модель считает Medicare levy как 2% годового дохода. Чистый годовой доход = валовой − налог − levy.", exampleNote: "При AUD 80 000 в год налог равен AUD 14 520, расчетный levy — AUD 1 600, чистый доход — AUD 63 880 в год (AUD 5 323,33 в месяц), до личных льгот и вычетов.", faq: { question: "Почему сумма отличается от расчетного листка?", answer: "Не учитываются личные вычеты, снижение или освобождение от levy, налоговое резидентство, учебный заем и индивидуальные удержания работодателя." } },
    "singapore-gross-net-salary-calculator": { description: "Оценка зарплаты по прогрессивному налогу резидента Сингапура и ставке CPF работника по возрасту. Налог нерезидентов, личные льготы, дополнительная зарплата и ступенчатые ставки CPF для новых PR не включены.", howTo: "Чтобы CPF рассчитывался по месячной базе, выберите месячную оплату и укажите зарплату до вычетов и возраст. Доля CPF работодателя не вычитается из чистой зарплаты работника.", formula: "Месячная зарплата умножается на 12 для годового налога резидента. CPF работника за год = min(введенная зарплата в месяц, SGD 8 000) × ставка возраста ×12; из годового дохода вычитаются налог и CPF работника.", exampleNote: "При SGD 6 000 в месяц и возрасте 35 лет: валовой доход SGD 72 000 в год, налог SGD 2 790, CPF работника SGD 14 400 в год, чистый доход SGD 54 810 (SGD 4 567,50 в месяц). Доля работодателя отдельно.", faq: { question: "Можно ли вводить годовую зарплату для CPF?", answer: "CPF рассчитывается по месячной зарплате и месячному лимиту. Используйте месячный режим; годовой режим применяет месячную формулу к исходному числу и не является официальной суммой взноса." } },
    "singapore-income-tax-calculator": { description: "Применяет прогрессивные ставки для резидентов Сингапура с YA 2024 к введенному годовому налогооблагаемому доходу. Ставки нерезидентов, личные льготы, возвраты и налоговые кредиты не учитываются.", howTo: "Введите годовой налогооблагаемый доход в SGD, по возможности после известных льгот. Валовая зарплата даст оценку до личных вычетов.", formula: "Для каждой предельной ступени умножьте часть дохода в ней на ставку и сложите суммы. Средняя ставка = налог ÷ введенный доход ×100; при нулевом доходе она равна 0.", exampleNote: "При облагаемом доходе SGD 100 000 налог по резидентским ступеням составляет SGD 5 650, средняя ставка — 5,65%. Личные льготы и возвраты не применены.", faq: { question: "Подходит ли расчет для нерезидентов?", answer: "Нет. Модель использует только прогрессивные ставки резидентов; трудовые и прочие доходы нерезидентов могут облагаться по другим правилам." } },
  },
  tr: {
    "australia-gross-net-salary-calculator": { description: "2026–27 yılında Avustralya vergi mukimleri için kademeli gelir vergisi ve sabit %2 Medicare levy düşülerek tahmin verir. Düşük gelir indirimi/muafiyeti, ek harç, indirimler ve mukim olmayan kuralları değerlendirilmez.", howTo: "Yıllık veya aylık ücreti seçip brüt tutarı girin. Aylık tutar 12 ile çarpılır; vergi ve levy kalemlerini ayrı inceleyin.", formula: "Yıllık gelir = aylık modda girilen tutar ×12. Vergi, 2026–27 mukim marjinal dilimlerinin toplamıdır; model Medicare levy'yi yıllık gelirin %2'si sayar. Net yıllık = brüt − vergi − levy.", exampleNote: "Yıllık AUD 80.000 için vergi AUD 14.520, model levy AUD 1.600 ve net AUD 63.880/yıl (AUD 5.323,33/ay) olur; kişisel indirimlerden önce.", faq: { question: "Sonuç neden maaş bordrosundan farklı olabilir?", answer: "Kişisel indirimler, levy azaltımı veya muafiyeti, vergi mukimliği, eğitim kredisi ve işveren stopaj ayrıntıları hesaba katılmaz." } },
    "singapore-gross-net-salary-calculator": { description: "Singapur mukimlerinin artan oranlı gelir vergisi ve yaşa göre çalışan CPF oranıyla maaş tahmini yapar. Mukim olmayan vergisi, kişisel indirimler, ek ücretler ve yeni PR için kademeli CPF oranları dahil değildir.", howTo: "CPF'yi aylık bazda eşlemek için aylık ödeme seçin; brüt maaş ve yaşı girin. İşveren CPF'si çalışanın net ücretinden düşülmez.", formula: "Aylık ücret mukim vergisi için ×12 ile yıllıklaştırılır. Yıllık çalışan CPF'si = min(girilen aylık ücret, SGD 8.000) × yaş oranı ×12; net tutardan vergi ve çalışan CPF'si çıkarılır.", exampleNote: "Aylık SGD 6.000 ve 35 yaşta yıllık brüt SGD 72.000, tahmini vergi SGD 2.790, çalışan CPF'si SGD 14.400/yıl ve net SGD 54.810/yıl (SGD 4.567,50/ay) olur. İşveren payı ayrıdır.", faq: { question: "CPF için yıllık maaş girebilir miyim?", answer: "CPF aylık ücret ve tavana dayanır. Aylık modu kullanın; yıllık mod aylık formülü ham tutara uygular ve resmi katkı tutarı değildir." } },
    "singapore-income-tax-calculator": { description: "Singapur mukimlerinin YA 2024'ten beri geçerli artan oranlı tarifesini girilen yıllık vergiye tabi gelire uygular. Mukim olmayan oranları, kişisel indirimler, iadeler ve vergi kredileri dahil değildir.", howTo: "Bilinen indirimlerden sonra yıllık vergiye tabi geliri SGD olarak girin. Brüt maaş girilirse kişisel indirimlerden önce tahmin yapılır.", formula: "Her marjinal dilimde kalan gelir parçasını oranıyla çarpıp toplayın. Ortalama oran = tahmini vergi ÷ girilen gelir ×100; sıfır gelirde 0'dır.", exampleNote: "SGD 100.000 vergiye tabi gelir, mukim dilimlerinde SGD 5.650 vergi ve %5,65 ortalama oran verir. Kişisel indirim ve iadeler uygulanmamıştır.", faq: { question: "Bu sonuç mukim olmayanlar için geçerli mi?", answer: "Hayır. Motor yalnız mukim tarifesini uygular; mukim olmayanların istihdam ve diğer gelirleri farklı kurallara tabi olabilir." } },
  },
  pl: {
    "australia-gross-net-salary-calculator": { description: "Szacunek dla rezydentów podatkowych Australii w 2026–27: odejmuje progresywny podatek dochodowy i stałą Medicare levy 2%. Nie ocenia ulg lub zwolnień dla niskich dochodów, dopłaty, odliczeń ani zasad dla nierezydentów.", howTo: "Wybierz pensję roczną lub miesięczną i wpisz kwotę brutto. Miesięczna jest mnożona przez 12; sprawdź osobno podatek i levy.", formula: "Dochód roczny = kwota ×12 w trybie miesięcznym. Podatek sumuje krańcowe progi rezydentów 2026–27; model liczy Medicare levy jako 2% dochodu rocznego. Netto roczne = brutto − podatek − levy.", exampleNote: "Przy AUD 80 000 rocznie podatek wynosi AUD 14 520, modelowa levy AUD 1 600, a netto AUD 63 880 rocznie (AUD 5 323,33 miesięcznie), przed ulgami i odliczeniami.", faq: { question: "Dlaczego wynik różni się od wypłaty?", answer: "Nie uwzględnia ulg i odliczeń, obniżenia lub zwolnienia z levy, rezydencji podatkowej, kredytu studenckiego ani szczegółów potrąceń pracodawcy." } },
    "singapore-gross-net-salary-calculator": { description: "Szacuje wynagrodzenie z progresywnym podatkiem rezydenta Singapuru i stawką CPF pracownika zależną od wieku. Pomija podatek nierezydentów, ulgi osobiste, dodatkowe płace i stopniowe stawki CPF nowych PR.", howTo: "Aby CPF liczyć od podstawy miesięcznej, wybierz wypłatę miesięczną i wpisz pensję brutto oraz wiek. CPF pracodawcy nie pomniejsza wypłaty netto pracownika.", formula: "Pensja miesięczna jest mnożona przez 12 do rocznego podatku rezydenta. Roczny CPF pracownika = min(podana pensja miesięczna, SGD 8 000) × stawka wieku ×12; netto odejmuje podatek i CPF pracownika od rocznego brutto.", exampleNote: "Przy SGD 6 000 miesięcznie i wieku 35 lat: brutto roczne SGD 72 000, szacowany podatek SGD 2 790, CPF pracownika SGD 14 400 rocznie, netto SGD 54 810 (SGD 4 567,50 miesięcznie). Udział pracodawcy osobno.", faq: { question: "Czy mogę podać pensję roczną do CPF?", answer: "CPF opiera się na płacy i limicie miesięcznym. Wybierz tryb miesięczny; tryb roczny stosuje miesięczny wzór do surowej wartości i nie daje oficjalnej kwoty składki." } },
    "singapore-income-tax-calculator": { description: "Stosuje progresywne stawki dla rezydentów Singapuru obowiązujące od YA 2024 do podanego rocznego dochodu podlegającego opodatkowaniu. Pomija stawki nierezydentów, ulgi osobiste, zwroty i kredyty podatkowe.", howTo: "Wpisz roczny dochód do opodatkowania w SGD, najlepiej po znanych ulgach. Wynagrodzenie brutto daje szacunek przed odliczeniami osobistymi.", formula: "Dla każdego progu krańcowego pomnóż część dochodu w progu przez stawkę i zsumuj. Średnia stawka = szacowany podatek ÷ wpisany dochód ×100; przy zerowym dochodzie wynosi 0.", exampleNote: "Dochód do opodatkowania SGD 100 000 daje SGD 5 650 podatku według progów rezydenta, średnio 5,65%. Ulgi i zwroty osobiste nie są zastosowane.", faq: { question: "Czy wynik dotyczy nierezydentów?", answer: "Nie. Silnik używa tylko progresywnej tabeli rezydentów; dochód z pracy i inne dochody nierezydentów mogą podlegać innym zasadom." } },
  },
  fil: {
    "australia-gross-net-salary-calculator": { description: "Tantiya para sa residenteng nagbabayad ng buwis sa Australia sa 2026–27 matapos ibawas ang progresibong income tax at nakapirming 2% Medicare levy. Hindi sinusuri ang low-income relief o exemption, surcharge, deduction, at tuntunin para sa nonresident.", howTo: "Pumili ng taunang o buwanang sahod at ilagay ang gross. Imumultiply sa 12 ang buwanang halaga; tingnan nang hiwalay ang buwis at levy.", formula: "Taunang sahod = inilagay na halaga ×12 sa buwanang mode. Pinagsasama ang marginal resident tax bands ng 2026–27; 2% ng taunang sahod ang levy sa modelo. Netong taon = gross − buwis − levy.", exampleNote: "Sa AUD 80,000 kada taon: buwis AUD 14,520, modeled levy AUD 1,600, netong AUD 63,880 kada taon (AUD 5,323.33 kada buwan), bago ang personal relief at deduction.", faq: { question: "Bakit iba ito sa netong nasa payslip?", answer: "Hindi sinusuri ang personal deductions, levy relief o exemption, tax residency, student-loan repayment, o partikular na withholding ng employer." } },
    "singapore-gross-net-salary-calculator": { description: "Tantiya ng sahod gamit ang progresibong buwis ng resident sa Singapore at CPF ng empleyado batay sa edad. Hindi kasama ang nonresident tax, personal relief, dagdag na sahod, at graduated CPF rates para sa bagong PR.", howTo: "Para sa buwanang batayan ng CPF, piliin ang buwanang sahod at ilagay ang gross pay at edad. Hindi ibinabawas ang CPF ng employer sa take-home ng empleyado.", formula: "Imumultiply sa 12 ang buwanang sahod para sa taunang resident tax. Taunang employee CPF = min(buwanang sahod na inilagay, SGD 8,000) × age rate ×12; ibinabawas ang buwis at employee CPF sa taunang gross.", exampleNote: "Sa SGD 6,000 buwanan at edad 35: taunang gross SGD 72,000, tinatayang buwis SGD 2,790, employee CPF SGD 14,400/taon at netong SGD 54,810/taon (SGD 4,567.50/buwan). Hiwalay ang bahagi ng employer.", faq: { question: "Maaari bang taunang sahod ang ilagay para sa CPF?", answer: "Buwanang sahod at limit ang batayan ng CPF. Gamitin ang buwanang mode; sa taunang mode, inilalapat ang buwanang formula sa raw na halaga kaya hindi ito opisyal na kontribusyon." } },
    "singapore-income-tax-calculator": { description: "Inilalapat ang progresibong resident tax rates ng Singapore mula YA 2024 sa inilagay na taunang taxable income. Hindi kasama ang nonresident rates, personal relief, rebate, at tax credit.", howTo: "Ilagay sa SGD ang taunang taxable income, kung maaari ay pagkatapos ng kilalang relief. Kung gross salary ang ilalagay, pagtataya ito bago ang personal relief.", formula: "I-multiply ang bahaging pasok sa bawat marginal band sa rate nito at pagsamahin. Average rate = tinatayang buwis ÷ inilagay na taxable income ×100; 0 kapag walang kita.", exampleNote: "Sa SGD 100,000 taxable income, SGD 5,650 ang buwis sa resident bands at 5.65% ang average rate. Hindi inilalapat ang personal relief o rebate.", faq: { question: "Para rin ba ito sa nonresident?", answer: "Hindi. Resident progressive bands lamang ang ginagamit; maaaring ibang tuntunin ang para sa employment at iba pang kita ng nonresident." } },
  },
  bn: {
    "australia-gross-net-salary-calculator": { description: "২০২৬–২৭ সালে অস্ট্রেলিয়ার কর-নিবাসীর জন্য প্রগতিশীল আয়কর ও স্থির ২% Medicare levy বাদ দিয়ে অনুমান। স্বল্প-আয়ের ছাড় বা অব্যাহতি, surcharge, কর্তন ও অনিবাসীর নিয়ম যাচাই করা হয় না।", howTo: "বার্ষিক বা মাসিক বেতন বেছে মোট বেতন লিখুন। মাসিক অঙ্ক ১২ দিয়ে গুণ হয়; কর ও levy আলাদা দেখুন।", formula: "বার্ষিক আয় = মাসিক মোডে দেওয়া অঙ্ক ×১২। ২০২৬–২৭ নিবাসী সীমান্তিক কর-ধাপ যোগ হয়; মডেল বার্ষিক আয়ের ২% Medicare levy ধরে। বার্ষিক নিট = মোট − কর − levy।", exampleNote: "বার্ষিক AUD 80,000 হলে কর AUD 14,520, মডেল levy AUD 1,600 এবং নিট AUD 63,880 (মাসে AUD 5,323.33); ব্যক্তিগত ছাড় ও কর্তনের আগে।", faq: { question: "পে-স্লিপের অঙ্কের সঙ্গে কেন পার্থক্য হতে পারে?", answer: "ব্যক্তিগত কর্তন, levy ছাড় বা অব্যাহতি, কর-নিবাস, শিক্ষা ঋণ এবং নিয়োগকর্তার withholding বিবেচিত হয় না।" } },
    "singapore-gross-net-salary-calculator": { description: "সিঙ্গাপুরের নিবাসী প্রগতিশীল আয়কর ও বয়সভিত্তিক কর্মচারী CPF দিয়ে বেতনের অনুমান। অনিবাসীর কর, ব্যক্তিগত ছাড়, অতিরিক্ত মজুরি ও নতুন PR-এর ধাপে ধাপে CPF হার অন্তর্ভুক্ত নয়।", howTo: "CPF-এর মাসিক ভিত্তি রাখতে মাসিক বেতন বেছে মোট মাসিক বেতন ও বয়স লিখুন। নিয়োগকর্তার CPF কর্মচারীর নিট বেতন থেকে বাদ যায় না।", formula: "মাসিক বেতন ×12 করে বার্ষিক নিবাসী কর হয়। বার্ষিক কর্মচারী CPF = min(দেওয়া মাসিক বেতন, SGD 8,000) × বয়সের হার ×12; বার্ষিক মোট থেকে কর ও কর্মচারী CPF বাদ যায়।", exampleNote: "মাসে SGD 6,000 ও বয়স 35 হলে বার্ষিক মোট SGD 72,000, কর অনুমান SGD 2,790, কর্মচারী CPF বছরে SGD 14,400 এবং নিট SGD 54,810 (মাসে SGD 4,567.50)। নিয়োগকর্তার অংশ আলাদা।", faq: { question: "CPF-এর জন্য বার্ষিক বেতন দেওয়া যাবে?", answer: "CPF মাসিক মজুরি ও সীমার ভিত্তিতে। মাসিক মোড নিন; বার্ষিক মোডে কাঁচা অঙ্কে মাসিক সূত্র প্রয়োগ হয়, তাই সরকারি অবদান হিসেবে নেবেন না।" } },
    "singapore-income-tax-calculator": { description: "YA 2024 থেকে সিঙ্গাপুরের নিবাসীদের প্রগতিশীল করহার দেওয়া বার্ষিক করযোগ্য আয়ে প্রয়োগ করে। অনিবাসীর হার, ব্যক্তিগত ছাড়, ফেরত ও কর-ক্রেডিট নেই।", howTo: "SGD-তে বার্ষিক করযোগ্য আয় লিখুন, সম্ভব হলে জানা ছাড় বাদ দিয়ে। মোট বেতন লিখলে ব্যক্তিগত ছাড়ের আগের অনুমান হবে।", formula: "প্রতিটি সীমান্তিক ধাপে থাকা আয়ের অংশকে সেই ধাপের হারে গুণ করে যোগ করুন। গড় হার = অনুমিত কর ÷ দেওয়া করযোগ্য আয় ×100; আয় শূন্য হলে 0।", exampleNote: "করযোগ্য আয় SGD 100,000 হলে নিবাসী ধাপ অনুযায়ী কর SGD 5,650, গড় হার 5.65%। ব্যক্তিগত ছাড় বা ফেরত প্রয়োগ হয়নি।", faq: { question: "অনিবাসীর জন্যও কি এই হার?", answer: "না। ইঞ্জিন শুধু নিবাসীর প্রগতিশীল ধাপ ব্যবহার করে; অনিবাসীর চাকরি ও অন্য আয়ে ভিন্ন নিয়ম হতে পারে।" } },
  },
  uk: {
    "australia-gross-net-salary-calculator": { description: "Оцінка для податкових резидентів Австралії за 2026–27 рік: віднімає прогресивний податок і фіксований Medicare levy 2%. Не визначає знижки чи звільнення для низького доходу, доплату, відрахування або правила нерезидентів.", howTo: "Оберіть річну або місячну зарплату й введіть суму до податків. Місячну суму множимо на 12; податок і levy показані окремо.", formula: "Річний дохід = введена сума ×12 у місячному режимі. Податок — сума граничних ставок резидентів 2026–27; модель рахує levy як 2% річного доходу. Чистий річний = валовий − податок − levy.", exampleNote: "За AUD 80 000 на рік податок становить AUD 14 520, модельний levy AUD 1 600, чистий дохід AUD 63 880 на рік (AUD 5 323,33 на місяць), до особистих пільг і відрахувань.", faq: { question: "Чому сума відрізняється від розрахункового листа?", answer: "Не враховуються особисті відрахування, зменшення чи звільнення від levy, податкове резидентство, студентська позика та індивідуальні утримання роботодавця." } },
    "singapore-gross-net-salary-calculator": { description: "Оцінює зарплату за прогресивним податком резидентів Сінгапуру та ставкою CPF працівника за віком. Податок нерезидентів, пільги, додаткові виплати й ступінчасті ставки CPF для нових PR не включені.", howTo: "Для місячної бази CPF виберіть місячну виплату та введіть брутто-зарплату й вік. Частка CPF роботодавця не віднімається від чистої зарплати працівника.", formula: "Місячна зарплата множиться на 12 для річного податку резидента. CPF працівника за рік = min(введена місячна зарплата, SGD 8 000) × вікова ставка ×12; із річного брутто віднімаються податок і CPF працівника.", exampleNote: "За SGD 6 000 на місяць і віку 35 років: річне брутто SGD 72 000, податок SGD 2 790, CPF працівника SGD 14 400 на рік, чистий дохід SGD 54 810 (SGD 4 567,50 на місяць). Частка роботодавця окрема.", faq: { question: "Чи можна ввести річну зарплату для CPF?", answer: "CPF базується на місячній зарплаті та ліміті. Оберіть місячний режим; річний режим застосовує місячну формулу до введеного числа й не дає офіційної суми внеску." } },
    "singapore-income-tax-calculator": { description: "Застосовує прогресивні ставки резидентів Сінгапуру від YA 2024 до введеного річного оподатковуваного доходу. Ставки нерезидентів, особисті пільги, повернення та податкові кредити не враховуються.", howTo: "Введіть річний оподатковуваний дохід у SGD, бажано після відомих пільг. Валовий оклад дає оцінку до особистих відрахувань.", formula: "Для кожного граничного діапазону помножте частину доходу в ньому на ставку й підсумуйте. Середня ставка = податок ÷ введений дохід ×100; за нульового доходу дорівнює 0.", exampleNote: "За оподатковуваного доходу SGD 100 000 податок за ставками резидента становить SGD 5 650, середня ставка 5,65%. Особисті пільги й повернення не застосовані.", faq: { question: "Чи підходить оцінка нерезидентам?", answer: "Ні. Розрахунок використовує лише прогресивну шкалу резидентів; зарплата та інші доходи нерезидентів можуть оподатковуватися інакше." } },
  },
  ms: {
    "australia-gross-net-salary-calculator": { description: "Anggaran untuk pemastautin cukai Australia pada 2026–27 dengan menolak cukai progresif dan Medicare levy tetap 2%. Pengurangan atau pengecualian pendapatan rendah, surcharge, potongan dan peraturan bukan pemastautin tidak dinilai.", howTo: "Pilih gaji tahunan atau bulanan dan masukkan gaji kasar. Gaji bulanan didarab 12; semak cukai dan levy secara berasingan.", formula: "Gaji tahunan = input ×12 dalam mod bulanan. Cukai menjumlahkan jalur marginal pemastautin 2026–27; model mengira levy sebagai 2% gaji tahunan. Bersih tahunan = kasar − cukai − levy.", exampleNote: "Gaji AUD 80,000 setahun menghasilkan cukai AUD 14,520, levy model AUD 1,600 dan bersih AUD 63,880 setahun (AUD 5,323.33 sebulan), sebelum pelepasan dan potongan peribadi.", faq: { question: "Mengapa berbeza daripada slip gaji?", answer: "Potongan peribadi, pengurangan atau pengecualian levy, pemastautin cukai, pinjaman pengajian dan butiran potongan majikan tidak dinilai." } },
    "singapore-gross-net-salary-calculator": { description: "Anggaran gaji menggunakan cukai progresif pemastautin Singapura dan kadar CPF pekerja mengikut umur. Cukai bukan pemastautin, pelepasan peribadi, upah tambahan dan kadar CPF berperingkat PR baharu tidak termasuk.", howTo: "Untuk asas CPF bulanan, pilih gaji bulanan dan masukkan gaji kasar serta umur. CPF majikan tidak ditolak daripada gaji bersih pekerja.", formula: "Gaji bulanan didarab 12 untuk cukai tahunan pemastautin. CPF tahunan pekerja = min(gaji bulanan yang dimasukkan, SGD 8,000) × kadar umur ×12; gaji bersih menolak cukai dan CPF pekerja daripada gaji tahunan.", exampleNote: "Pada SGD 6,000 sebulan dan umur 35: kasar tahunan SGD 72,000, cukai anggaran SGD 2,790, CPF pekerja SGD 14,400 setahun dan bersih SGD 54,810 (SGD 4,567.50 sebulan). Bahagian majikan berasingan.", faq: { question: "Bolehkah saya masukkan gaji tahunan untuk CPF?", answer: "CPF berdasarkan upah dan had bulanan. Pilih mod bulanan; mod tahunan menggunakan formula bulanan pada nilai mentah dan bukan jumlah caruman rasmi." } },
    "singapore-income-tax-calculator": { description: "Menggunakan kadar progresif pemastautin Singapura sejak YA 2024 pada pendapatan bercukai tahunan yang dimasukkan. Kadar bukan pemastautin, pelepasan peribadi, bayaran balik dan kredit cukai tidak termasuk.", howTo: "Masukkan pendapatan bercukai tahunan dalam SGD, sebaiknya selepas pelepasan yang diketahui. Gaji kasar memberikan anggaran sebelum potongan peribadi.", formula: "Darab bahagian pendapatan dalam setiap jalur marginal dengan kadarnya, kemudian jumlahkan. Kadar purata = cukai anggaran ÷ pendapatan input ×100; 0 jika pendapatan sifar.", exampleNote: "Pendapatan bercukai SGD 100,000 menghasilkan cukai SGD 5,650 mengikut jalur pemastautin, kadar purata 5.65%. Pelepasan peribadi dan bayaran balik tidak digunakan.", faq: { question: "Adakah ini terpakai kepada bukan pemastautin?", answer: "Tidak. Enjin hanya menggunakan jalur progresif pemastautin; pendapatan pekerjaan dan lain-lain bagi bukan pemastautin boleh tertakluk pada peraturan berbeza." } },
  },
  sv: {
    "australia-gross-net-salary-calculator": { description: "Uppskattning för australiska skatteresidenter 2026–27: progressiv inkomstskatt och en fast Medicare levy på 2 % dras av. Låginkomstreduktion eller undantag, tilläggsavgift, avdrag och regler för icke-residenter prövas inte.", howTo: "Välj års- eller månadslön och ange bruttolön. Månadslön multipliceras med 12; granska skatt och levy var för sig.", formula: "Årsinkomst = inmatat belopp ×12 i månadsläge. Skatten summerar residenternas marginalskikt 2026–27; modellen räknar levy som 2 % av årsinkomsten. Netto per år = brutto − skatt − levy.", exampleNote: "Vid AUD 80 000 per år: skatt AUD 14 520, modellerad levy AUD 1 600 och netto AUD 63 880 per år (AUD 5 323,33 per månad), före personliga avdrag och lättnader.", faq: { question: "Varför avviker beloppet från lönebeskedet?", answer: "Personliga avdrag, sänkning eller undantag från levy, skatterättslig hemvist, studielån och arbetsgivarens skatteavdrag bedöms inte." } },
    "singapore-gross-net-salary-calculator": { description: "Löneuppskattning med Singapores progressiva residentinkomstskatt och anställdas CPF efter ålder. Icke-residentskatt, personliga lättnader, tilläggslön och stegvisa CPF-satser för nya PR ingår inte.", howTo: "Välj månadslön för CPF:s månadsbas och ange bruttolön samt ålder. Arbetsgivarens CPF dras inte från den anställdes nettolön.", formula: "Månadslön multipliceras med 12 för residenternas årsskatt. Årlig CPF för anställd = min(inmatad månadslön, 8 000 SGD) × ålderssats ×12; nettot drar skatt och anställd-CPF från årslönen.", exampleNote: "Vid 6 000 SGD/månad och 35 år: årsbrutto 72 000 SGD, skatt 2 790 SGD, anställd-CPF 14 400 SGD/år och netto 54 810 SGD/år (4 567,50 SGD/månad). Arbetsgivarandelen är separat.", faq: { question: "Kan jag ange årslön för CPF?", answer: "CPF baseras på månadslön och ett månadstak. Använd månadsläge; årsläget tillämpar månadsformeln på råvärdet och är inte ett officiellt bidragsbelopp." } },
    "singapore-income-tax-calculator": { description: "Tillämpar Singapores progressiva residentnivåer från YA 2024 på angiven årlig beskattningsbar inkomst. Icke-residentskatt, personliga lättnader, återbetalningar och skatteavdrag ingår inte.", howTo: "Ange årlig beskattningsbar inkomst i SGD, helst efter kända lättnader. Bruttolön ger en uppskattning före personliga avdrag.", formula: "Multiplicera inkomstens del i varje marginalskikt med skattesatsen och summera. Genomsnittlig skattesats = skatt ÷ angiven inkomst ×100; 0 vid noll inkomst.", exampleNote: "Beskattningsbar inkomst på 100 000 SGD ger 5 650 SGD enligt residentskikten, i genomsnitt 5,65 %. Personliga lättnader och återbetalningar har inte tillämpats.", faq: { question: "Gäller detta även icke-residenter?", answer: "Nej. Motorn använder bara residentskalan; arbets- och andra inkomster för icke-residenter kan omfattas av andra regler." } },
  },
  cs: {
    "australia-gross-net-salary-calculator": { description: "Odhad pro australské daňové rezidenty za rok 2026–27: odečítá progresivní daň z příjmu a pevný Medicare levy 2 %. Neposuzuje snížení či osvobození nízkých příjmů, příplatek, odpočty ani pravidla pro nerezidenty.", howTo: "Vyberte roční nebo měsíční mzdu a zadejte hrubou částku. Měsíční mzda se násobí 12; daň a levy sledujte zvlášť.", formula: "Roční příjem = zadaná částka ×12 v měsíčním režimu. Daň sčítá mezní pásma rezidentů 2026–27; model počítá levy jako 2 % ročního příjmu. Roční čistý příjem = hrubý − daň − levy.", exampleNote: "Při AUD 80 000 ročně činí daň AUD 14 520, modelový levy AUD 1 600 a čistý příjem AUD 63 880 ročně (AUD 5 323,33 měsíčně), před osobními úlevami a odpočty.", faq: { question: "Proč se výsledek liší od výplatní pásky?", answer: "Model neposuzuje osobní odpočty, snížení či osvobození levy, daňovou rezidenci, studentskou půjčku ani konkrétní srážky zaměstnavatele." } },
    "singapore-gross-net-salary-calculator": { description: "Odhad mzdy pomocí progresivní daně rezidentů Singapuru a zaměstnanecké sazby CPF podle věku. Nezahrnuje daň nerezidentů, osobní úlevy, dodatečné mzdy ani postupné sazby CPF nových PR.", howTo: "Pro měsíční základ CPF zvolte měsíční mzdu a zadejte hrubou mzdu a věk. Příspěvek CPF zaměstnavatele se z čisté mzdy zaměstnance neodečítá.", formula: "Měsíční mzda se násobí 12 pro roční daň rezidenta. Roční CPF zaměstnance = min(zadaná měsíční mzda, 8 000 SGD) × sazba podle věku ×12; čistá mzda odečítá daň a CPF zaměstnance od ročního hrubého příjmu.", exampleNote: "Při 6 000 SGD měsíčně a věku 35 let: roční hrubý příjem 72 000 SGD, daň 2 790 SGD, CPF zaměstnance 14 400 SGD/rok a čistý příjem 54 810 SGD/rok (4 567,50 SGD/měsíc). Podíl zaměstnavatele je zvlášť.", faq: { question: "Lze pro CPF zadat roční mzdu?", answer: "CPF vychází z měsíční mzdy a měsíčního limitu. Použijte měsíční režim; roční režim aplikuje měsíční vzorec na surovou hodnotu a nejde o oficiální příspěvek." } },
    "singapore-income-tax-calculator": { description: "Používá progresivní sazby pro rezidenty Singapuru platné od YA 2024 na zadaný roční zdanitelný příjem. Nezahrnuje sazby nerezidentů, osobní úlevy, vratky ani daňové kredity.", howTo: "Zadejte roční zdanitelný příjem v SGD, nejlépe po známých úlevách. Hrubá mzda znamená odhad před osobními odpočty.", formula: "Část příjmu v každém mezním pásmu vynásobte jeho sazbou a sečtěte. Průměrná sazba = odhad daně ÷ zadaný příjem ×100; při nulovém příjmu je 0.", exampleNote: "Zdanitelný příjem 100 000 SGD dává podle rezidentských pásem daň 5 650 SGD, průměrnou sazbu 5,65 %. Osobní úlevy ani vratky nejsou započteny.", faq: { question: "Platí výsledek i pro nerezidenty?", answer: "Ne. Výpočet používá pouze progresivní sazby rezidentů; pracovní a jiné příjmy nerezidentů mohou podléhat jiným pravidlům." } },
  },
  ro: {
    "australia-gross-net-salary-calculator": { description: "Estimare pentru rezidenții fiscali australieni în 2026–27: scade impozitul progresiv și Medicare levy fix de 2%. Nu evaluează reducerile sau scutirile pentru venituri mici, suprataxa, deducerile ori regulile nerezidenților.", howTo: "Alegeți salariul anual sau lunar și introduceți brutul. Salariul lunar se înmulțește cu 12; verificați separat impozitul și levy.", formula: "Venit anual = suma introdusă ×12 în modul lunar. Impozitul însumează tranșele marginale pentru rezidenți 2026–27; modelul calculează levy ca 2% din venitul anual. Net anual = brut − impozit − levy.", exampleNote: "La AUD 80.000 anual: impozit AUD 14.520, levy modelat AUD 1.600 și net AUD 63.880 pe an (AUD 5.323,33 lunar), înaintea reducerilor și deducerilor personale.", faq: { question: "De ce diferă de fluturașul de salariu?", answer: "Nu sunt evaluate deducerile personale, reducerea sau scutirea levy, rezidența fiscală, creditul pentru studii ori reținerile specifice angajatorului." } },
    "singapore-gross-net-salary-calculator": { description: "Estimare salarială cu impozitul progresiv pentru rezidenții din Singapore și CPF al angajatului în funcție de vârstă. Exclude impozitul nerezidenților, facilitățile personale, salariile suplimentare și ratele CPF graduale pentru PR noi.", howTo: "Pentru baza lunară CPF, selectați plata lunară și introduceți salariul brut și vârsta. CPF-ul angajatorului nu se scade din netul angajatului.", formula: "Salariul lunar se anualizează ×12 pentru impozitul rezidentului. CPF anual al angajatului = min(salariul lunar introdus, SGD 8.000) × rata de vârstă ×12; netul scade impozitul și CPF-ul angajatului din brutul anual.", exampleNote: "La SGD 6.000 lunar și 35 de ani: brut anual SGD 72.000, impozit estimat SGD 2.790, CPF angajat SGD 14.400/an și net SGD 54.810/an (SGD 4.567,50/lună). Partea angajatorului este separată.", faq: { question: "Pot introduce salariul anual pentru CPF?", answer: "CPF se bazează pe salariul și plafonul lunar. Folosiți modul lunar; modul anual aplică formula lunară valorii brute și nu reprezintă contribuția oficială." } },
    "singapore-income-tax-calculator": { description: "Aplică veniturilor impozabile anuale introduse tranșele progresive pentru rezidenții din Singapore valabile din YA 2024. Nu include ratele nerezidenților, facilități personale, rambursări sau credite fiscale.", howTo: "Introduceți venitul impozabil anual în SGD, ideal după facilitățile cunoscute. Salariul brut oferă o estimare înaintea deducerilor personale.", formula: "Înmulțiți partea venitului din fiecare tranșă marginală cu rata ei și însumați. Rata medie = impozit estimat ÷ venit introdus ×100; este 0 când venitul este 0.", exampleNote: "Un venit impozabil de SGD 100.000 produce SGD 5.650 după tranșele rezidente, cu rată medie de 5,65%. Facilitățile personale și rambursările nu sunt aplicate.", faq: { question: "Este valabil și pentru nerezidenți?", answer: "Nu. Motorul folosește doar grila progresivă a rezidenților; venitul profesional și alte venituri ale nerezidenților pot urma reguli diferite." } },
  },
  el: {
    "australia-gross-net-salary-calculator": { description: "Εκτίμηση για φορολογικούς κατοίκους Αυστραλίας το 2026–27: αφαιρεί προοδευτικό φόρο και σταθερή εισφορά Medicare levy 2%. Δεν ελέγχει μειώσεις ή απαλλαγές χαμηλού εισοδήματος, πρόσθετη επιβάρυνση, εκπτώσεις ή κανόνες μη κατοίκων.", howTo: "Επιλέξτε ετήσιο ή μηνιαίο μισθό και εισαγάγετε τις μικτές αποδοχές. Ο μηνιαίος μισθός πολλαπλασιάζεται επί 12· δείτε χωριστά φόρο και levy.", formula: "Ετήσιο εισόδημα = εισαγωγή ×12 στη μηνιαία λειτουργία. Ο φόρος αθροίζει τα οριακά κλιμάκια κατοίκων 2026–27· το μοντέλο υπολογίζει levy ως 2% του ετήσιου εισοδήματος. Καθαρό ετήσιο = μικτό − φόρος − levy.", exampleNote: "Με AUD 80.000 ετησίως: φόρος AUD 14.520, μοντελοποιημένο levy AUD 1.600 και καθαρό AUD 63.880 ετησίως (AUD 5.323,33 μηνιαίως), πριν από προσωπικές μειώσεις και εκπτώσεις.", faq: { question: "Γιατί διαφέρει από το εκκαθαριστικό μισθοδοσίας;", answer: "Δεν αξιολογούνται προσωπικές εκπτώσεις, μείωση ή απαλλαγή levy, φορολογική κατοικία, φοιτητικό δάνειο ή οι ειδικές παρακρατήσεις του εργοδότη." } },
    "singapore-gross-net-salary-calculator": { description: "Εκτίμηση μισθού με τον προοδευτικό φόρο κατοίκων της Σιγκαπούρης και CPF εργαζομένου ανά ηλικία. Δεν περιλαμβάνει φόρο μη κατοίκων, προσωπικές ελαφρύνσεις, πρόσθετες αποδοχές ή κλιμακωτά ποσοστά CPF νέων PR.", howTo: "Για μηνιαία βάση CPF επιλέξτε μηνιαία αμοιβή και εισαγάγετε μικτό μισθό και ηλικία. Η εργοδοτική CPF δεν αφαιρείται από τις καθαρές αποδοχές εργαζομένου.", formula: "Ο μηνιαίος μισθός πολλαπλασιάζεται επί 12 για τον ετήσιο φόρο κατοίκου. Ετήσια CPF εργαζομένου = min(εισαγόμενος μηνιαίος μισθός, SGD 8.000) × ποσοστό ηλικίας ×12· το καθαρό αφαιρεί φόρο και CPF εργαζομένου από το ετήσιο μικτό.", exampleNote: "Με SGD 6.000 μηνιαίως και ηλικία 35: ετήσιο μικτό SGD 72.000, φόρος SGD 2.790, CPF εργαζομένου SGD 14.400/έτος και καθαρό SGD 54.810/έτος (SGD 4.567,50/μήνα). Η εργοδοτική εισφορά είναι χωριστή.", faq: { question: "Μπορώ να εισαγάγω ετήσιο μισθό για CPF;", answer: "Το CPF βασίζεται σε μηνιαίες αποδοχές και όριο. Επιλέξτε μηνιαία λειτουργία· η ετήσια λειτουργία εφαρμόζει τον μηνιαίο τύπο στην ακατέργαστη τιμή και δεν είναι επίσημη εισφορά." } },
    "singapore-income-tax-calculator": { description: "Εφαρμόζει τις προοδευτικές κλίμακες κατοίκων Σιγκαπούρης από το YA 2024 στο εισαγόμενο ετήσιο φορολογητέο εισόδημα. Δεν περιλαμβάνει φόρους μη κατοίκων, προσωπικές ελαφρύνσεις, επιστροφές ή φορολογικές πιστώσεις.", howTo: "Εισαγάγετε ετήσιο φορολογητέο εισόδημα σε SGD, κατά προτίμηση μετά τις γνωστές ελαφρύνσεις. Ο μικτός μισθός δίνει εκτίμηση πριν από αυτές.", formula: "Πολλαπλασιάστε το τμήμα εισοδήματος σε κάθε οριακή κλίμακα με τον συντελεστή και αθροίστε. Μέσος συντελεστής = εκτιμώμενος φόρος ÷ εισαγόμενο εισόδημα ×100· είναι 0 όταν το εισόδημα είναι 0.", exampleNote: "Φορολογητέο εισόδημα SGD 100.000 δίνει φόρο SGD 5.650 βάσει κλιμάκων κατοίκων και μέσο συντελεστή 5,65%. Προσωπικές ελαφρύνσεις και επιστροφές δεν εφαρμόζονται.", faq: { question: "Ισχύει αυτό και για μη κατοίκους;", answer: "Όχι. Ο μηχανισμός χρησιμοποιεί μόνο την προοδευτική κλίμακα κατοίκων· η εργασία και άλλα εισοδήματα μη κατοίκων μπορεί να διέπονται από διαφορετικούς κανόνες." } },
  },
};
